def route(message):
    text = message.lower()
    if 'invoice' in text or 'refund' in text:
        return 'billing'
    elif 'crash' in text or 'error' in text:
        return 'tech'
    return 'general'

messages = [
    'my invoice is wrong',
    'app crashes on login',
    'what are your hours',
]

counts = {'billing': 0, 'tech': 0, 'general': 0}
for m in messages:
    agent = route(m)
    print(f"'{m}' -> {agent}")
    counts[agent] += 1

print(f"Handoffs: billing={counts['billing']} tech={counts['tech']} general={counts['general']}")
